// ============================================================
// Follow-up Cron v2 — smart messages based on sales_state
// ============================================================

const SUPABASE_URL = 'https://xfibcjhshpmqkrhlpsoa.supabase.co';
const SUPABASE_KEY = 'eyJ-REDACTED-SERVICE-ROLE';
const SB_HEADERS = {
  apikey: SUPABASE_KEY,
  Authorization: `Bearer ${SUPABASE_KEY}`,
  'Content-Type': 'application/json',
  Prefer: 'return=representation',
};

const DELAYS = { quoted: 30, interested: 120, followup: 1440 };
const BLOCKED = ['closed','lost','handoff','manual_quote','new'];

// ── رسائل حسب followup_type / sales_state ─────────────────────
function buildMessage(lead) {
  const n   = lead.name        || 'بك';
  const dst = lead.destination || 'الوجهة';
  const ft  = lead.followup_type;
  const ss  = lead.sales_state;
  const idx = lead.follow_up_count || 0;  // 0 = أول follow-up, 1 = ثاني

  // 1. أرخص / اعتراض سعر
  if (ft === 'cheaper_option' || ss === 'price_objection') {
    return idx === 0
      ? `هلا ${n} 👋\nلقيت لك خيار بسعر أوفر لـ${dst}! تحب أشاركه معك؟ 😊`
      : `${n} مرحباً 🌟\nالعرض الاقتصادي لـ${dst} لا يزال متاحاً — خبرنا قبل ما ينتهي!`;
  }

  // 2. يريد بديلاً
  if (ft === 'send_alternative' || ss === 'requesting_alt') {
    return idx === 0
      ? `هلا ${n} 👋\nجهّزت لك خيار مختلف لـ${dst} — تحب أشوفك الآن؟ 🏨`
      : `${n} 😊 لو لسه بتفكر، عندي خيارات متعددة تناسب ميزانيتك!`;
  }

  // 3. جاهز للحجز
  if (ss === 'ready_to_book') {
    return idx === 0
      ? `هلا ${n} 🎉\nباقي خطوة واحدة لحجز رحلتك لـ${dst}! تحب نكمل الآن؟`
      : `${n} 👋 الأماكن محدودة لـ${dst} — نكمل الحجز قبل ما تنتهي؟`;
  }

  // 4. عميل دافئ / مهتم
  if (ss === 'warm_lead' || ft === 'interest_follow_up') {
    return idx === 0
      ? `هلا ${n} 😊\nكيف حالك؟ لو قررت الحجز لـ${dst} نرتب كل شيء خلال دقائق!`
      : `${n} مرحباً 🌍\nلو محتاج تفاصيل إضافية عن ${dst} أخبرنا — نحن هنا!`;
  }

  // 5. تذكير بعد quote (الافتراضي)
  if (ft === 'quote_follow_up' || lead.stage === 'quoted') {
    return idx === 0
      ? `هلا ${n} 👋\nبس أتأكد وصلك العرض؟ لو عندك أي سؤال أو تعديل نحن هنا 😊`
      : `مرحباً ${n} 🌟\nاليوم آخر يوم نضمن نفس السعر لـ${dst} — تحب نكمل الحجز؟`;
  }

  // 6. عام / followup
  return idx === 0
    ? `هلا ${n} 👋\nمجرد تذكير ودي — لو في أي وقت تحب نتكلم عن رحلة ${dst} نحن موجودين 😊`
    : `${n} مرحباً 🌟\nفرص السفر لـ${dst} متاحة — خبرنا لما يناسبك!`;
}

// ── Helpers ───────────────────────────────────────────────────
async function sbGet(path) {
  return await this.helpers.httpRequest({
    method: 'GET', url: `${SUPABASE_URL}/rest/v1/${path}`,
    headers: SB_HEADERS, json: true,
  });
}
async function sbPatch(path, body) {
  return await this.helpers.httpRequest({
    method: 'PATCH', url: `${SUPABASE_URL}/rest/v1/${path}`,
    headers: SB_HEADERS, body, json: true,
  });
}
async function sendWhatsApp(phone, message) {
  await this.helpers.httpRequest({
    method: 'POST', url: 'https://n8n.arcadia-tour.cloud/webhook/send-message',
    headers: { 'Content-Type': 'application/json' },
    body: { phone, message }, json: true,
  });
}

// ── Main ──────────────────────────────────────────────────────
const now     = new Date();
const results = { sent: [], skipped: [], errors: [] };
const stageFilter = BLOCKED.map(s => `stage=neq.${s}`).join('&');

const dueLeads = await sbGet.call(this,
  `leads?paused=eq.false&follow_up_count=lt.2&next_followup=lte.${now.toISOString()}&${stageFilter}&select=*`
);

if (!Array.isArray(dueLeads) || dueLeads.length === 0) {
  return [{ json: { status: 'idle', checked_at: now.toISOString() } }];
}

for (const lead of dueLeads) {
  try {
    // تخطى إذا needs_human = true (يحتاج تدخل بشري)
    if (lead.needs_human) {
      results.skipped.push({ id: lead.lead_id, reason: 'needs_human', phone: lead.phone });
      continue;
    }

    // تخطى إذا intent_score منخفض جداً (< 2)
    if (lead.intent_score !== null && lead.intent_score < 2) {
      results.skipped.push({ id: lead.lead_id, reason: 'low_intent:' + lead.intent_score });
      continue;
    }

    const message  = buildMessage(lead);
    const newCount = (lead.follow_up_count || 0) + 1;
    const delay    = DELAYS[lead.stage];
    const nextFU   = newCount < 2 && delay
      ? new Date(Date.now() + delay * 60 * 1000).toISOString()
      : null;

    // log intended message before sending (for audit even on failure)
    console.log(`[CRON] msg to ${lead.phone}: ${message.slice(0,80)}`);
    results.attempted = results.attempted || [];
    results.attempted.push({ phone: lead.phone, sales_state: lead.sales_state, followup_type: lead.followup_type, message_preview: message.slice(0,80) });

    await sendWhatsApp.call(this, lead.phone, message);
    await sbPatch.call(this, `leads?lead_id=eq.${lead.lead_id}`, {
      follow_up_count: newCount,
      next_followup: nextFU,
    });

    results.sent.push({
      id:           lead.lead_id,
      phone:        lead.phone,
      stage:        lead.stage,
      sales_state:  lead.sales_state  || null,
      followup_type:lead.followup_type || null,
      intent_score: lead.intent_score  ?? null,
      fu_index:     newCount - 1,
      message_preview: message.slice(0, 60),
    });

    console.log(`[CRON] sent to ${lead.phone} | ss=${lead.sales_state} ft=${lead.followup_type} idx=${newCount-1}`);
  } catch(err) {
    results.errors.push({ id: lead.lead_id, error: err.message });
  }
}

return [{ json: { ...results, checked_at: now.toISOString() } }];
